-- PG17.6. Solo SELECT. Exportar columna payload_text sin alterar bytes UTF8.
-- No remitir fuera de LF sin autorización y minimización del corpus.
BEGIN READ ONLY;
WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE codigo='CLIENT_PAYMENTS' UNION SELECT n.codigo,n.padre FROM lf_ops.nucleo_nodos n JOIN anc a ON n.codigo=a.padre), des AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE codigo='CLIENT_PAYMENTS' UNION SELECT n.codigo,n.padre FROM lf_ops.nucleo_nodos n JOIN des d ON n.padre=d.codigo), sc AS (SELECT codigo FROM anc UNION SELECT codigo FROM des), native AS (SELECT r.codigo,v.version,jsonb_build_object('regla',to_jsonb(r),'version',to_jsonb(v),'aplicaciones',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.nodo) FROM lf_ops.nucleo_aplicaciones a WHERE a.regla=r.codigo),'[]'::jsonb)) x FROM lf_ops.nucleo_reglas r JOIN lf_ops.nucleo_regla_versiones v ON v.regla=r.codigo WHERE v.estado IN ('PUBLICADA','CANDIDATA') AND r.codigo<>'REG_CHK_007' AND (r.familia='PAYMENTS_CHECKOUT' OR EXISTS(SELECT 1 FROM lf_ops.nucleo_aplicaciones a JOIN sc ON sc.codigo=a.nodo WHERE a.regla=r.codigo))), legacy AS (SELECT r.id,jsonb_build_object('regla',to_jsonb(r),'enlaces',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) FROM lf_ops.reglas_pantallas p WHERE p.regla_id=r.id),'[]'::jsonb)) x FROM lf_ops.reglas r WHERE r.estado IN ('VIGENTE','CANDIDATO') AND r.codigo<>'REG_CHK_007' AND (r.es_transversal OR EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_familia f WHERE f.regla_id=r.id AND f.familia='PAYMENTS_CHECKOUT') OR EXISTS(SELECT 1 FROM lf_ops.reglas_pantallas p JOIN lf_ops.nucleo_nodos n ON n.pantalla_id=p.pantalla_id JOIN sc ON sc.codigo=n.codigo WHERE p.regla_id=r.id))), corpus AS (SELECT jsonb_build_object('nucleo',(SELECT jsonb_agg(x ORDER BY codigo,version) FROM native),'legado',(SELECT jsonb_agg(x ORDER BY id) FROM legacy),'nodos',(SELECT jsonb_agg(to_jsonb(n) ORDER BY n.codigo) FROM lf_ops.nucleo_nodos n JOIN sc ON sc.codigo=n.codigo)) x), focal AS (SELECT n.codigo,jsonb_build_object('instancia','lf_ops','regla_version_aplicaciones',n.x,'hash_paquete_oficial',encode(sha256(convert_to((n.x->'version'->>'hash')||'|'||coalesce((SELECT string_agg(p.n||':'||coalesce(p.casuistica,'')||':'||p.entrada::text||':'||p.esperado::text,'|' ORDER BY p.n) FROM lf_ops.nucleo_regla_pruebas p WHERE p.regla=n.codigo AND p.version=2),''),'UTF8')),'hex'),'pruebas',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.n) FROM lf_ops.nucleo_regla_pruebas p WHERE p.regla=n.codigo AND p.version=2),'legado',(SELECT x FROM legacy WHERE id=CASE n.codigo WHEN 'REG_CHK_002' THEN 156 ELSE 183 END),'autoridad',(SELECT to_jsonb(a) FROM lf_ops.nucleo_autoridades a WHERE a.codigo=n.x->'version'->>'autoridad'),'hechos',(SELECT jsonb_agg(to_jsonb(h) ORDER BY h.codigo) FROM lf_ops.nucleo_hechos h WHERE (n.codigo='REG_CHK_002' AND h.codigo='checkout_items') OR (n.codigo='REG_TEC_007' AND h.codigo IN ('checkout_en_confirmacion','conexion_disponible'))),'rubrica',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.codigo) FROM lf_ops.nucleo_rubrica r WHERE estado='ACTIVO'),'umbral',(SELECT jsonb_agg(to_jsonb(g) ORDER BY valid_from) FROM public.lf_global_config g WHERE scope='NUCLEO_EVAL' AND config_key='UMBRAL_DIMENSION'),'hash_corpus',encode(sha256(convert_to(c.x::text,'UTF8')),'hex')) x FROM native n CROSS JOIN corpus c WHERE n.codigo IN ('REG_CHK_002','REG_TEC_007') AND n.version=2), expected(codigo,hash) AS (VALUES ('REG_CHK_002','74d53e01b4fa40c4dbfd395fe37a27341135320dcc8199ee6aacd2baad8df5f0'),('REG_TEC_007','3ec3cc0ff2b18fe00108629506e932ae0f4562843ed2631242c2447c47c59166'),('CORPUS','78adbe41eeccd9183f5ca48116a2a78883d1b5a95d00924ef512785433a7b2c0')), payloads AS (SELECT codigo,x FROM focal UNION ALL SELECT 'CORPUS',x FROM corpus), checked AS (SELECT p.codigo,p.x::text payload_text,encode(sha256(convert_to(p.x::text,'UTF8')),'hex') hash_actual,e.hash hash_esperado FROM payloads p JOIN expected e USING(codigo)) SELECT codigo,hash_actual,hash_esperado,hash_actual=hash_esperado coincide,CASE WHEN (SELECT count(*)=3 AND bool_and(hash_actual=hash_esperado) FROM checked) THEN payload_text ELSE NULL END payload_text FROM checked ORDER BY codigo;
ROLLBACK;
